sylphen_dd_fieldmapping.calculation:
if(!$params['response']->hasContent()) {
    $params['response']->headers->set('Content-Type', 'text/xml');
    $result = "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<result>";
} else {
    $result = '';
}

$writeTag = function($data) use (&$writeTag) {
    $result = '';
    if(is_array($data)) {
        foreach($data as $tagName => $valueItem) {
            if(is_numeric($tagName)) {
                $tagName = 'item';
            }
            $result .= '<'.preg_replace('/[^\p{L}\p{Nd}]/u', '_', $tagName).'>';
            if($valueItem instanceof \stdClass || is_array($valueItem)) {
                $result .= $writeTag((array)$valueItem);
            } else {
                $result .= '<![CDATA['.$valueItem.']]>';
            }
            $result .= '</'.preg_replace('/[^\p{L}\p{Nd}]/u', '_', $tagName).'>';
        }
    } else {
        $result .= '<![CDATA['.$data.']]>';
    }

    return $result;
};

$decodeValue = function($value) {
    if(is_string($value) && !is_numeric($value)) {
        $decodedValue = json_decode($value, true);
        if (json_last_error() === \JSON_ERROR_NONE) {
            $value = $decodedValue;
        }
    }

    return $value;
};

$result .= '<item>';
$result .= '<ID>';
$result .= $writeTag($decodeValue({{ ID }}));
$result .= '</ID>';


$result .= '<Published>';
$result .= $writeTag($decodeValue({{ Published }}));
$result .= '</Published>';


$result .= '<Name>';
$result .= $writeTag($decodeValue({{ Name }}));
$result .= '</Name>';


$result .= '<SKU>';
$result .= $writeTag($decodeValue({{ SKU }}));
$result .= '</SKU>';


$result .= '<Price>';
$result .= $writeTag($decodeValue({{ Price }}));
$result .= '</Price>';


$result .= '<Description>';
$result .= $writeTag($decodeValue({{ Description }}));
$result .= '</Description>';


$result .= '<Images>';
$result .= $writeTag($decodeValue({{ Images }}));
$result .= '</Images>';


$result .= '<Brand___Name>';
$result .= $writeTag($decodeValue({{ Brand > Name }}));
$result .= '</Brand___Name>';


$result .= '</item>';

if($params['lastCall']) {
    $result .= '</result>';
}

$params['response']->addContent($result);
